import { asString, useSearchParam } from '../../url/useSearchParam';
import { showDue } from '../rates/due';
import { STATUSES, useSheetFigures } from '../people/useSheetFigures';

// The sheet's counters, always on show: its people (retired included), its claims per status (as
// the summary counts them) and its due-total and overdue-total (as the sheet's totals show them).
// Then the signed-in user's own figures: the due-total and overdue-total of the person on the sheet
// with the user's name or alias (case and outer spaces ignored); nothing when there is no such person.
export function SheetHeader() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const { people, sheetDueTotal, sheetOverdueTotal, statusCount, totalOf, overdue, overdueTotal } = useSheetFigures(sheet);
  const key = (name: string) => name.trim().toLowerCase();
  const me = user === '' ? undefined : people.find((p) => [p.name, ...p.aliases].some((n) => key(n) === key(user)));
  return (
    <header data-testid="header">
      People: <span data-testid="header-people-count">{people.length}</span>
      {STATUSES.map((s) => (
        <span key={s}>
          {' · '}
          {s}: <span data-testid={`header-claims-${s}-count`}>{statusCount(s)}</span>
        </span>
      ))}
      {' · '}Due: <span data-testid="header-due-total">{sheetDueTotal}</span>
      {' · '}Overdue: <span data-testid="header-overdue-total">{sheetOverdueTotal}</span>
      {' · '}Mine: due <span data-testid="my-due-total">{me ? showDue(totalOf(me)) : ''}</span>
      {', '}overdue <span data-testid="my-overdue-total">{me ? overdueTotal(overdue.filter((c) => c.personId === me.id)) : ''}</span>
    </header>
  );
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { formatCents } from '../rates/due';
import type { Person } from '../people/usePeople';
import { useSheetFigures } from '../people/useSheetFigures';
import { crewsKey, useCrews, type Crew } from './useCrews';

// The sheet's crews and the form that adds one: a name (a blank name, or one already a crew, is refused)
// and a lead chosen from the people. Each crew shows its lead and its due-total — the lead's and the
// members' due-totals added up, n/a skipped — and adds a member from its row: the lead, or a person
// already in the crew, is refused.
export function CrewPanel() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const crews = useCrews(sheet);
  const { people, byId, totalOf } = useSheetFigures(sheet);
  const [name, setName] = useState('');
  const [leadId, setLeadId] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();
  const add = useMutation({
    mutationFn: (body: { name: string; leadId: string }) =>
      postJson<Crew[]>(`/api/sheets/${encodeURIComponent(sheet)}/crews`, { ...body, user }),
    onSuccess: (saved) => {
      setName('');
      setLeadId('');
      queryClient.setQueryData(crewsKey(sheet), saved);
    },
  });
  const dueTotalOf = (crew: Crew) =>
    formatCents(
      [crew.leadId, ...crew.members.map((m) => m.personId)].reduce((sum, id) => {
        const person = byId.get(id);
        const due = person === undefined ? null : totalOf(person);
        return due === null ? sum : sum + due;
      }, 0n),
    );
  return (
    <>
      <ul data-testid="crew-list">
        {crews.map((c) => (
          <CrewRow key={c.name} crew={c} dueTotal={dueTotalOf(c)} people={people} sheet={sheet} user={user} />
        ))}
      </ul>
      <form
        data-testid="crew-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            add.reset();
            return add.mutateAsync({ name: name.trim(), leadId });
          });
        }}
      >
        <input
          data-testid="crew-form-name"
          value={name}
          placeholder="Crew name"
          onChange={(e) => {
            setName(e.target.value);
            add.reset();
          }}
        />{' '}
        <select
          data-testid="crew-form-lead"
          value={leadId}
          onChange={(e) => {
            setLeadId(e.target.value);
            add.reset();
          }}
        >
          <option value="">Choose a lead</option>
          {people.map((p) => (
            <option key={p.id} value={p.id}>{p.name}</option>
          ))}
        </select>{' '}
        <button type="submit" data-testid="crew-form-submit">Add crew</button>
        {add.isError && <span data-testid="crew-form-error" role="alert"> Could not add the crew: its name must not be blank or already a crew, and it needs a lead.</span>}
      </form>
    </>
  );
}

function CrewRow({ crew, dueTotal, people, sheet, user }: { crew: Crew; dueTotal: string; people: Person[]; sheet: string; user: string }) {
  const [personId, setPersonId] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();
  const add = useMutation({
    mutationFn: (body: { personId: string }) =>
      postJson<Crew[]>(`/api/sheets/${encodeURIComponent(sheet)}/crew-members`, { ...body, crew: crew.name, user }),
    onSuccess: (saved) => {
      setPersonId('');
      queryClient.setQueryData(crewsKey(sheet), saved);
    },
  });
  return (
    <li data-testid={`crew-row-${crew.name}`}>
      <span data-testid="crew-name">{crew.name}</span>{' '}
      lead <span data-testid="crew-lead">{crew.leadName}</span>{' '}
      due-total <span data-testid="crew-due-total">{dueTotal}</span>
      <ul>
        {crew.members.map((m) => (
          <li key={m.personId} data-testid="crew-member-line">
            <span data-testid="crew-member-name">{m.name}</span>
          </li>
        ))}
      </ul>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            add.reset();
            return add.mutateAsync({ personId });
          });
        }}
      >
        <select
          data-testid="crew-member-select"
          value={personId}
          onChange={(e) => {
            setPersonId(e.target.value);
            add.reset();
          }}
        >
          <option value="">Choose a person</option>
          {people.map((p) => (
            <option key={p.id} value={p.id}>{p.name}</option>
          ))}
        </select>{' '}
        <button type="submit" data-testid="crew-member-add">Add member</button>
        {add.isError && <span data-testid="crew-error" role="alert"> Could not add the member: they lead the crew or are already in it.</span>}
      </form>
    </li>
  );
}

